{
  "passageId": "joseon-slavery-civil-rights",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 노비가 물적 성격을 지니면서도 일부 자유와 권리를 인정받았다는 양면성을 제시한다."
    },
    {
      "id": "R2",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "노비 수의 증감을 기준으로 조선 전기와 왜란·호란 이후라는 두 시기의 추세를 대조한다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노비 수와 신분 격차의 변화가 실제로 노비에 대한 인식 변화를 일으켰다고 설명한다."
    },
    {
      "id": "R4",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "노비에 대한 인식 변화가 양반들의 새로운 노비 관련 글이 등장한 사상적 배경이 된다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "양반들의 노비 관련 글이라는 앞의 내용을 그 글에 담긴 구체적인 시각과 한계로 풀어 설명한다."
    },
    {
      "id": "R6",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "노비를 연약한 존재로 바라보는 시선이 온정적 차원을 넘어서지는 못했다는 한계를 제시한다."
    },
    {
      "id": "R7",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "같은 양반들이 노비의 의지는 강조하면서도 불평등한 처지는 거론하지 않았다는 한계를 드러낸다."
    },
    {
      "id": "R8",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "노비에 대한 미안함을 드러냈지만 신분 질서에 대한 비판까지 나아가지는 않았음을 밝힌다."
    },
    {
      "id": "R9",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "노비 문제를 바라보는 기존 양반들과 이익의 서로 다른 관점을 나란히 제시한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "운명의 세 분류를 인간사의 관여 여부와 능동적 변화 가능성이라는 세부 내용으로 구체화한다."
    },
    {
      "id": "R11",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "한 이론 안에서 천명·성명과 조명을 인간의 능동적 개입 가능성이라는 기준으로 대조한다."
    },
    {
      "id": "R12",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "조명의 대상 범위에 관한 이전 학자들과 이익의 견해 차이를 제시한다."
    },
    {
      "id": "R13",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "모든 사람이 조명의 대상이라는 내용을 누구나 노력으로 운명을 바꿀 수 있다는 말로 풀어 다시 진술한다."
    },
    {
      "id": "R14",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "개인의 노력과 재주·덕행을 중시하는 원리가 노비 매매·세습 금지와 기회 개방 주장을 뒷받침한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "삶의 변화가 개인의 몫이라는 관점이 국가의 역할을 최소한의 기반 보장으로 한정하는 근거가 된다."
    },
    {
      "id": "R16",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "서구 기본권 사상의 유입이 민권 논의가 구체화된 사상적 배경으로 제시된다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "유길준의 한 이론 안에서 천부 인권과 인위적 권리의 절대성·상대성 및 성립 근거를 대조한다."
    },
    {
      "id": "R18",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "근대 법률의 제정과 시행을 천부 인권의 실질적 보장을 위한 수단으로 제시한다."
    },
    {
      "id": "R19",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "근대 법률의 제정과 시행을 인위적 권리의 실질적 보장을 위한 수단으로 제시한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "민이 무지하다는 인식이 교육받지 않은 민은 사회 혼란을 초래할 수 있다는 판단의 근거가 된다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "유길준이 민의 권리 보장을 주장하면서도 민을 무지하고 혼란을 일으킬 수 있는 존재로 본 양면성을 드러낸다."
    },
    {
      "id": "R22",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "유길준과 박영효가 모두 민의 권리 보장에서 법의 필수성을 인정한다는 공통점을 보인다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "타고난 능력에 따라 귀천이 생긴다는 주장을 부림의 정당성을 뒷받침하는 근거로 삼는다."
    },
    {
      "id": "R24",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 온건 개화파가 노비 세습 금지를 지지하면서도 귀천과 부림을 정당화하는 양면성을 보인다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "개화파의 민권 주장이 여러 상황과 함께 실제 신분제 폐지 조치를 이끌었다고 설명한다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "온건 개화파를 포함한 개화파의 민권 주장이 다른 상황들과 맞물려 법제상 신분제 폐지로 이어졌다고 서술한다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "법으로 신분제를 폐지했는데도 노비가 남아 있었다는 법과 현실의 괴리를 제시한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "법제상 신분제 폐지에도 사회적 차별이 지속되었다는 제도적 조치의 한계를 드러낸다."
    },
    {
      "id": "R29",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "노비와 사회적 차별이 잔존한 상황이 독립 협회의 비판이 제기된 사회적 배경이 된다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자유와 평등이 천부의 권리라는 원리가 노비 소유와 매매를 비판하는 근거로 쓰인다."
    },
    {
      "id": "R31",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "신분 차별의 지속이라는 논의를 갑오개혁 이후에서 일제 강점기로 시대를 옮겨 이어 간다."
    },
    {
      "id": "R32",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "일제 강점기에도 지속된 신분 차별이 백정의 인권을 요구하는 형평 운동의 발생 배경으로 제시된다."
    },
    {
      "id": "R33",
      "type": "PROCESS",
      "otherName": "",
      "reason": "형평사 조직으로 운동이 시작된 단계에서 참여 세력의 결합으로 본격화되는 단계로 이어진다."
    },
    {
      "id": "R34",
      "type": "PROCESS",
      "otherName": "",
      "reason": "운동의 본격화 다음에 대중의 호응과 전국화가 이어지는 발전 순서를 서술한다."
    },
    {
      "id": "R35",
      "type": "OTHER",
      "otherName": "성격의 병렬",
      "reason": "인권 운동과 공동체 운동은 서로의 하위 범주가 아니라 형평 운동이 함께 지닌 두 성격으로 병렬된다."
    },
    {
      "id": "R36",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "운동의 도화선이 된 교육 차별이 형평 운동에서 교육 활동을 펼치게 된 배경으로 제시된다."
    },
    {
      "id": "R37",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사회적 대우를 받으려면 소양이 필요하다는 인식이 교육 활동을 추진하는 근거가 된다."
    },
    {
      "id": "R38",
      "type": "OTHER",
      "otherName": "실천의 병행",
      "reason": "일상적 실천과 제도화 노력은 같은 목적을 위한 병행 활동으로 제시되며 명시적인 선후나 인과는 없다."
    },
    {
      "id": "R39",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "형평 운동의 형성과 활동에 관한 논의에서 위축·변질 및 후대의 영향에 관한 논의로 넘어간다."
    },
    {
      "id": "R40",
      "type": "PROCESS",
      "otherName": "",
      "reason": "대동사 개칭 시점에 운동이 본래 성격을 잃는 변화의 단계를 서술하며 개칭 자체의 인과 작용을 주장하지는 않는다."
    },
    {
      "id": "R41",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "형평 운동이 본래 성격을 잃었지만 후대 인권 운동에 영향을 남겼다는 역사적 의의를 제시한다."
    }
  ]
}

